/* @lc app=leetcode id=2813 lang=kotlin */ class Solution { fun findMaximumElegance(items: Array<IntArray>, k: Int): Long = items.sortedByDescending { it[0] }.let { s -> HashSet<Int>().let { cat -> ArrayList<Int>().let { dups -> s.take(k).fold(0L) { t, (p, c) -> (if (cat.add(c)) 0 else dups.add(p).let { 0 }).let { t + p } }.let { t0 -> (t0 + cat.size.toLong() * cat.size).let { best0 -> s.drop(k).fold(Triple(t0, best0, 0)) { (t, best, _), (p, c) -> if (c in cat || dups.isEmpty()) Triple(t, best, 0) else dups.removeAt(dups.size - 1).let { d -> cat.add(c).let { (t - d + p).let { t2 -> Triple(t2, maxOf(best, t2 + cat.size.toLong() * cat.size), 0) } } } }.second } } } } } }